import backtrader as bt
import math
from collections import deque


class MultiStrategyORBIncome(bt.Strategy):
    params = ()

    def __init__(self):
        self.bb = bt.indicators.BollingerBands(self.data.close, period=20, devfactor=2.0)
        self.atr = bt.indicators.ATR(self.data, period=14)
        self.ema = bt.indicators.EMA(self.data.close, period=20)
        self.rsi = bt.indicators.RSI(self.data.close, period=14)
        self.volume_sma = bt.indicators.SMA(self.data.volume, period=20)
        self.crossover = bt.indicators.CrossOver(self.data.close, self.bb.mid)
        self.bandwidth_history = deque(maxlen=252)
        self.order = None
        self.order_meta = {}
        self.trades = {1: None, 2: None, 3: None}
        self.pending = {1: None, 2: None, 3: None}
        self.log_records = []
        self.session_date = None
        self.session_bar = 0
        self.or_high = None
        self.or_low = None

    def _record(self, event, strategy, **values):
        record = {
            'datetime': self.data.datetime.datetime(0),
            'event': event,
            'strategy': strategy,
        }
        record.update(values)
        self.log_records.append(record)

    def _percentile_rank(self, value):
        return 100.0 * sum(x <= value for x in self.bandwidth_history) / len(self.bandwidth_history)

    def _exposure(self, strategy):
        trade = self.trades[strategy]
        pending = self.pending[strategy]
        if trade is not None:
            return trade['size'] * float(self.data.close[0])
        if pending is not None and pending['action'] == 'entry':
            return pending['size'] * float(self.data.close[0])
        return 0.0

    def _enter(self, strategy, direction, stop, percentile, target=None):
        price = float(self.data.close[0])
        risk_distance = price - stop if direction == 1 else stop - price
        if risk_distance <= 0.0:
            return
        allocation = {1: 0.40, 2: 0.30, 3: 0.30}[strategy] * 150000.0
        risk_size = int(round(1500.0 / risk_distance))
        allocation_size = int(math.floor(allocation / price))
        size = min(risk_size, allocation_size)
        if size < 1 or self._exposure(strategy) + size * price > allocation:
            return
        order = self.buy(size=size) if direction == 1 else self.sell(size=size)
        meta = {
            'action': 'entry', 'strategy': strategy, 'direction': direction,
            'size': size, 'stop': stop, 'signal_price': price,
            'risk_distance': risk_distance, 'target': target,
            'entry_bar': len(self), 'percentile': percentile,
        }
        self.pending[strategy] = meta
        self.order_meta[order.ref] = meta
        self.order = order
        self._record('signal', strategy, direction=direction, price=price,
                     size=size, stop=stop, bandwidth_percentile=percentile)

    def _exit(self, strategy, reason, price):
        trade = self.trades[strategy]
        if trade is None or self.pending[strategy] is not None:
            return
        order = self.sell(size=trade['size']) if trade['direction'] == 1 else self.buy(size=trade['size'])
        r_multiple = ((price - trade['entry']) * trade['direction']) / trade['risk_distance']
        meta = {'action': 'exit', 'strategy': strategy, 'size': trade['size'],
                'reason': reason, 'r_multiple': r_multiple}
        self.pending[strategy] = meta
        self.order_meta[order.ref] = meta
        self.order = order
        self._record('exit_signal', strategy, reason=reason, price=price,
                     r_multiple=r_multiple, bandwidth_percentile=trade['percentile'])

    def notify_order(self, order):
        if order.status in (order.Submitted, order.Accepted):
            return
        meta = self.order_meta.pop(order.ref, None)
        if meta is None:
            return
        strategy = meta['strategy']
        if order.status == order.Completed:
            if meta['action'] == 'entry':
                entry = order.executed.price
                risk_distance = entry - meta['stop'] if meta['direction'] == 1 else meta['stop'] - entry
                if strategy == 1:
                    half_r = entry + meta['direction'] * 0.5 * risk_distance
                    middle = meta['target']
                    target = min(middle, half_r) if meta['direction'] == 1 else max(middle, half_r)
                elif strategy == 3:
                    target = entry + meta['direction'] * 2.0 * risk_distance
                else:
                    target = meta['target']
                self.trades[strategy] = {
                    'direction': meta['direction'], 'size': meta['size'],
                    'entry': entry, 'stop': meta['stop'], 'target': target,
                    'risk_distance': risk_distance, 'entry_bar': len(self),
                    'percentile': meta['percentile'],
                }
                self._record('entry', strategy, price=entry, size=meta['size'],
                             bandwidth_percentile=meta['percentile'])
            else:
                self._record('exit', strategy, price=order.executed.price,
                             reason=meta['reason'], r_multiple=meta['r_multiple'])
                self.trades[strategy] = None
        self.pending[strategy] = None
        if self.order is order:
            self.order = None

    def next(self):
        dt = self.data.datetime.datetime(0)
        if self.session_date != dt.date():
            self.session_date = dt.date()
            self.session_bar = 0
            self.or_high = None
            self.or_low = None
        self.session_bar += 1
        if self.session_bar <= 6:
            high = float(self.data.high[0])
            low = float(self.data.low[0])
            self.or_high = high if self.or_high is None else max(self.or_high, high)
            self.or_low = low if self.or_low is None else min(self.or_low, low)

        middle = float(self.bb.mid[0])
        bandwidth = (float(self.bb.top[0]) - float(self.bb.bot[0])) / middle
        self.bandwidth_history.append(bandwidth)
        if len(self.bandwidth_history) < 252:
            return
        percentile = self._percentile_rank(bandwidth)
        close = float(self.data.close[0])
        atr = float(self.atr[0])
        eod = dt.hour == 15 and dt.minute == 55

        for strategy in (1, 2, 3):
            trade = self.trades[strategy]
            if trade is None or self.pending[strategy] is not None:
                continue
            direction = trade['direction']
            if strategy == 1:
                if (direction == 1 and float(self.data.low[0]) <= trade['stop']) or (direction == -1 and float(self.data.high[0]) >= trade['stop']):
                    self._exit(1, 'stop', close)
                elif (direction == 1 and float(self.data.high[0]) >= trade['target']) or (direction == -1 and float(self.data.low[0]) <= trade['target']):
                    self._exit(1, 'take_profit', close)
                elif len(self) - trade['entry_bar'] >= 5:
                    self._exit(1, 'timeout', close)
            elif strategy == 2:
                if (direction == 1 and float(self.data.low[0]) <= trade['stop']) or (direction == -1 and float(self.data.high[0]) >= trade['stop']):
                    self._exit(2, 'stop', close)
                elif (direction == 1 and float(self.data.high[0]) >= trade['target']) or (direction == -1 and float(self.data.low[0]) <= trade['target']):
                    self._exit(2, 'take_profit', close)
                elif eod:
                    self._exit(2, 'eod', close)
            else:
                if direction == 1:
                    trail = max(float(self.ema[0]), close - atr)
                    trade['stop'] = max(trade['stop'], trail)
                    stop_hit = float(self.data.low[0]) <= trade['stop']
                    target_hit = float(self.data.high[0]) >= trade['target']
                else:
                    trail = max(float(self.ema[0]), close + atr)
                    trade['stop'] = min(trade['stop'], trail)
                    stop_hit = float(self.data.high[0]) >= trade['stop']
                    target_hit = float(self.data.low[0]) <= trade['target']
                if stop_hit:
                    self._exit(3, 'atr_trailing_stop', close)
                elif target_hit:
                    self._exit(3, 'take_profit_2R', close)
                elif eod:
                    self._exit(3, 'eod', close)

        if eod or percentile < 10.0 or self.session_bar <= 6:
            return
        if float(self.data.volume[0]) < float(self.volume_sma[0]):
            return

        active = sum(self.trades[s] is not None or self.pending[s] is not None for s in (1, 2, 3))
        if active >= 3:
            return
        if self.trades[1] is None and self.pending[1] is None and percentile <= 30.0:
            if float(self.data.high[0]) >= float(self.bb.top[0]) and float(self.rsi[0]) > 60.0:
                self._enter(1, -1, float(self.bb.top[0]) + atr, percentile, middle)
            elif float(self.data.low[0]) <= float(self.bb.bot[0]) and float(self.rsi[0]) < 40.0:
                self._enter(1, 1, float(self.bb.bot[0]) - atr, percentile, middle)

        mid_or = (self.or_high + self.or_low) / 2.0
        if self.trades[2] is None and self.pending[2] is None and 70.0 <= percentile <= 90.0:
            if float(self.data.high[0]) > self.or_high and close < self.or_high:
                self._enter(2, -1, self.or_high + 0.5 * atr, percentile, mid_or)
            elif float(self.data.low[0]) < self.or_low and close > self.or_low:
                self._enter(2, 1, self.or_low - 0.5 * atr, percentile, mid_or)

        if self.trades[3] is None and self.pending[3] is None:
            if close > self.or_high and float(self.data.close[-1]) > self.or_high and float(self.ema[0]) > float(self.ema[-1]):
                stop = max(close - atr, self.or_low)
                self._enter(3, 1, stop, percentile)
            elif close < self.or_low and float(self.data.close[-1]) < self.or_low and float(self.ema[0]) < float(self.ema[-1]):
                stop = min(close + atr, self.or_high)
                self._enter(3, -1, stop, percentile)
